_ABSOLUTE_ZERO_C = -273.15


def _to_celsius(value, unit):
    if unit == "C":
        return value
    if unit == "F":
        return (value - 32) * 5 / 9
    if unit == "K":
        return value - 273.15
    raise ValueError(f"unknown unit {unit!r}")


def _from_celsius(value, unit):
    if unit == "C":
        return value
    if unit == "F":
        return value * 9 / 5 + 32
    if unit == "K":
        return value + 273.15
    raise ValueError(f"unknown unit {unit!r}")


def convert(value, source, target):
    """Converts a temperature between Celsius (C), Fahrenheit (F) and Kelvin (K).

    Raises ValueError for unknown units or a value below absolute zero.
    """
    if source not in ("C", "F", "K") or target not in ("C", "F", "K"):
        raise ValueError(f"cannot convert {source} to {target}")
    if source == "K":
        below = value < 0
    elif source == "C":
        below = value < _ABSOLUTE_ZERO_C
    else:
        below = value < -459.67
    if below:
        raise ValueError(f"{value} {source} is below absolute zero")
    if source == target:
        return value
    return _from_celsius(_to_celsius(value, source), target)

