import pytest
from temperature import convert


def test_celsius_to_fahrenheit():
    assert convert(100, "C", "F") == pytest.approx(212)


def test_fahrenheit_to_celsius():
    assert convert(32, "F", "C") == pytest.approx(0)


def test_celsius_to_kelvin():
    assert convert(0, "C", "K") == pytest.approx(273.15)


def test_kelvin_to_celsius():
    assert convert(300, "K", "C") == pytest.approx(26.85)


def test_kelvin_fahrenheit_roundtrip():
    assert convert(convert(100, "F", "K"), "K", "F") == pytest.approx(100)


def test_absolute_zero_allowed():
    assert convert(0, "K", "C") == pytest.approx(-273.15)


@pytest.mark.parametrize("value,unit", [(-1, "K"), (-273.16, "C"), (-459.68, "F")])
def test_below_absolute_zero_refused(value, unit):
    with pytest.raises(ValueError):
        convert(value, unit, "C")


def test_unknown_unit_refused():
    with pytest.raises(ValueError):
        convert(1, "X", "C")
    with pytest.raises(ValueError):
        convert(1, "C", "X")
    with pytest.raises(ValueError):
        convert(1, "X", "X")

